import React from 'react';
import { Link } from 'react-router-dom';

export default function BookCard({book}){
  const cover = book.coverUrl ? (book.coverUrl.startsWith('/uploads') ? `${process.env.REACT_APP_API || 'http://localhost:5000'}${book.coverUrl}` : book.coverUrl) : 'https://via.placeholder.com/300x420?text=Cover';
  return (
    <div className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-xl transition">
      <Link to={`/books/${book._id}`}>
        <img src={cover} alt={book.title} className="w-full h-64 object-cover" />
        <div className="p-4">
          <h3 className="font-semibold text-lg">{book.title}</h3>
          <p className="text-sm text-gray-500">{book.author}</p>
          <div className="flex items-center justify-between mt-3">
            <div className="text-blue-600 font-bold">Rs {book.price}</div>
            <div className="text-sm text-gray-500">{book.stock > 0 ? 'In stock' : 'Out'}</div>
          </div>
        </div>
      </Link>
    </div>
  );
}
